package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import java.util.function.Consumer;
final class CreationPreviewAcceptance {
    static String target(WorkflowSupport h,String name)throws Exception{try(var db=h.store.open()){return RecordAccess.owner(db,name);}}
    static String api(String target){return "/api/openservice/users/"+target+"/creation-preview";}
    static Map<String,Object> body(String kind,String table,Object values){return map("kind",kind,"table",table,"values",values);}
    static Map<String,Object> retained(Store store)throws Exception{try(var db=store.open()){var counts=map();for(String table:List.of("os_record","os_event","os_requester_record","os_work","os_approval","os_security_event"))counts.put(table,db.count("SELECT COUNT(*) FROM "+table));counts.put("sequence",db.count(db.postgres?"SELECT last_value FROM os_record_seq_seq":"SELECT COALESCE((SELECT seq FROM sqlite_sequence WHERE name='os_record'),0)"));return counts;}}
    static Map<String,Object> preview(WorkflowSupport h,String target,Object input)throws Exception{var before=retained(h.store);var r=h.json("POST",api(target),input,auth("admin"));assertEquals(200,r.statusCode(),html(r));assertEquals(before,retained(h.store));return object(parsed(r).get("result"));}
    static void matches(WorkflowSupport h,String user,String kind,String table,Map<String,Object> values,int expected)throws Exception{var result=preview(h,target(h,user),body(kind,table,values));assertEquals(expected,result.get("status"));assertEquals(expected==201,result.get("allowed"));var real=h.json("POST",kind.equals("request")?"/api/openservice/requests":"/api/now/table/"+table,values,auth(user));assertEquals(expected,real.statusCode(),html(real));}
    static void configure(WorkflowSupport h,String table,Consumer<Map<String,Object>> change)throws Exception{Map<String,Object> schema;try(var db=h.store.open()){schema=Service.schema(db,table);}change.accept(schema);var r=h.json("POST","/api/openservice/configuration?dry_run=false",ConfigurationAcceptance.bundle(table,schema),auth("admin"));assertEquals(200,r.statusCode(),html(r));}
    static void run(WorkflowSupport h)throws Exception{
        h.account("CreateAgent","agent");h.account("CreateReader","reader");h.account("CreateRequester","requester");String agent=target(h,"CreateAgent"),admin=target(h,"admin");var valid=map("short_description","Proposed <script> work");
        matches(h,"CreateAgent","record","incident",valid,201);matches(h,"admin","record","incident",valid,201);matches(h,"CreateRequester","record","incident",valid,403);matches(h,"CreateReader","record","incident",valid,403);matches(h,"CreateReader","request","sc_request",valid,403);matches(h,"CreateRequester","request","sc_request",valid,201);matches(h,"CreateAgent","request","sc_request",valid,201);
        matches(h,"CreateRequester","request","sc_request",map("short_description","No extra values","state","open"),400);matches(h,"CreateAgent","record","incident",map("short_description",""),400);matches(h,"CreateAgent","record","missing_table",valid,404);
        for(Object bad:List.of(map(),body("unknown","incident",valid),body("record","Bad-name",valid),body("request","incident",valid),body("record","incident","not an object"),body("record","incident",map("short_description","x".repeat(65537)))))assertEquals(400,h.json("POST",api(agent),bad,auth("admin")).statusCode());
        assertEquals(404,h.json("POST",api(id()),body("record","incident",valid),auth("admin")).statusCode());assertEquals(403,h.json("POST",api(agent),body("record","incident",valid),auth("CreateAgent")).statusCode());assertEquals(403,h.json("POST",api(agent),body("record","incident",valid),auth("CreateReader")).statusCode());assertEquals(401,h.json("POST",api(agent),body("record","incident",valid),null).statusCode());assertEquals(405,h.get(api(agent),auth("admin")).statusCode());assertEquals(400,h.json("POST",api(agent)+"?x=y",body("record","incident",valid),auth("admin")).statusCode());
        try(var db=h.store.open()){Service.changeActive(db,PlatformFoundationTest.bind(db),agent,map("active",false));db.connection.commit();}var blocked=preview(h,agent,body("record","incident",valid));assertEquals(false,blocked.get("allowed"));assertEquals("Account is inactive",blocked.get("message"));
        try(var db=h.store.open()){Service.changeActive(db,PlatformFoundationTest.bind(db),agent,map("active",true));PasswordReset.require(db,admin,agent);db.connection.commit();}assertEquals("Password replacement is required",preview(h,agent,body("record","incident",valid)).get("message"));
        try(var db=h.store.open()){PlatformFoundationTest.bind(db);db.update("UPDATE os_user SET password_reset_required=0 WHERE user_id=?",agent);db.connection.commit();}
        String ui="/admin/accounts/"+agent+"/creation-preview";assertEquals(200,h.get(ui,auth("admin")).statusCode());assertEquals(404,h.get(ui.replace(agent,id()),auth("admin")).statusCode());assertEquals(400,h.get(ui+"?x=y",auth("admin")).statusCode());var form=map("kind","record","table","incident","values",JSON.writeValueAsString(valid));assertEquals(403,h.form(ui,form,auth("admin")).statusCode());var before=retained(h.store);var page=h.protectedForm(ui,form,auth("admin"));assertEquals(200,page.statusCode(),html(page));assertTrue(html(page).contains("Allowed by current checks"));assertTrue(html(page).contains("&lt;script&gt;"));assertEquals(before,retained(h.store));
        for(var bad:List.of(map("kind","record"),map("kind","record","table","incident","values","{"),map("kind","record","table","incident","values","[]"),map("kind","record","table","incident","values","")))assertEquals(400,h.protectedForm(ui,bad,auth("admin")).statusCode());
        try(var db=h.store.open()){PlatformFoundationTest.bind(db);CreationPreview.inspect(db,admin,agent,body("record","incident",valid));assertEquals(admin,db.viewerId);assertEquals("admin",db.viewerRole);db.update("ALTER TABLE os_schema RENAME TO temporarily_unavailable_schema");assertThrows(java.sql.SQLException.class,()->CreationPreview.inspect(db,admin,agent,body("record","incident",valid)));assertEquals(admin,db.viewerId);assertEquals("admin",db.viewerRole);db.connection.rollback();}
        new Store(h.environment);assertEquals(true,preview(h,agent,body("record","incident",valid)).get("allowed"));
    }
    static void policies(WorkflowSupport h)throws Exception{
        h.account("PolicyCreator","agent");String agent=target(h,"PolicyCreator"),admin=target(h,"admin");var a=new ConfigurationAcceptance(h);
        try{
            var schema=ConfigurationAcceptance.definition();schema.put("states",map("open","Open","closed","Closed"));schema.put("flow",map("open",List.of("closed"),"closed",List.of()));object(schema.get("fields")).put("state","State");object(schema.get("fields")).put("asset","Asset");object(schema.get("field_rules")).put("asset",map("type","reference","target","cmdb_ci"));assertEquals(200,a.install(ConfigurationAcceptance.bundle(a.table,schema),false).statusCode());
            var values=map("short_description","Policy work","category","service");matches(h,"PolicyCreator","record",a.table,values,201);matches(h,"PolicyCreator","record",a.table,map("short_description","Policy work","quantity","not integer"),400);matches(h,"PolicyCreator","record",a.table,map("short_description","Policy work","state","closed"),400);
            configure(h,a.table,s->s.put("record_roles",map("create",List.of("admin"))));matches(h,"PolicyCreator","record",a.table,values,403);
            configure(h,a.table,s->s.put("record_roles",map("read",List.of("admin"))));matches(h,"PolicyCreator","record",a.table,values,403);
            configure(h,a.table,s->{s.remove("record_roles");object(object(s.get("field_rules")).get("quantity")).put("write_roles",List.of("admin"));object(object(s.get("field_rules")).get("amount")).put("read_roles",List.of("admin"));});
            matches(h,"PolicyCreator","record",a.table,map("short_description","Policy work","quantity","4"),403);matches(h,"PolicyCreator","record",a.table,map("short_description","Policy work","amount",""),403);
            configure(h,a.table,s->s.put("transition_rules",map("open",map("roles",List.of("admin")))));matches(h,"PolicyCreator","record",a.table,values,403);
            configure(h,a.table,s->s.put("transition_rules",map("open",map("required_fields",List.of("category")))));matches(h,"PolicyCreator","record",a.table,map("short_description","Missing required category"),400);var complete=map("short_description","Policy work","category","service");matches(h,"PolicyCreator","record",a.table,complete,201);
            // Configuration rejects new protected initial states; simulate a retained legacy definition to prove the defensive creation gate is shared.
            try(var db=h.store.open()){var legacy=Service.schema(db,a.table);legacy.put("transition_rules",map("open",map("min_approvals",1)));db.update("UPDATE os_schema SET definition="+db.jsonParameter()+" WHERE name=?",JSON.writeValueAsString(legacy),a.table);db.connection.commit();}matches(h,"PolicyCreator","record",a.table,complete,409);
            configure(h,a.table,s->s.remove("transition_rules"));String asset=h.add("cmdb_ci").get("sys_id").toString(),group=h.add("sys_user_group").get("sys_id").toString();try(var db=h.store.open()){PlatformFoundationTest.bind(db);RecordAccess.change(db,Service.record(db,"cmdb_ci",asset),admin,map("visibility","group","group_id",group));GroupMembers.change(db,group,admin,map("user_id",agent),true);db.connection.commit();}
            var reference=map("short_description","Scoped asset","asset",asset);matches(h,"PolicyCreator","record",a.table,reference,201);try(var db=h.store.open()){PlatformFoundationTest.bind(db);GroupMembers.change(db,group,admin,map("user_id",agent),false);db.connection.commit();}matches(h,"PolicyCreator","record",a.table,reference,400);
            try(var db=h.store.open()){PlatformFoundationTest.bind(db);assertEquals(false,CreationPreview.inspect(db,admin,agent,body("record",a.table,reference)).get("allowed"));assertEquals(admin,db.viewerId);assertEquals("admin",db.viewerRole);}
        }finally{a.cleanup();}
    }
}
